S = SS('w10')
steps = [
    step("用代码算 CIDR:同一个地址 10.1.2.200,前缀 /8 → 网络号 10.0.0.0、广播 10.255.255.255、可用主机 16777214;/16 → 10.1.0.0、10.1.255.255、65534;/22 → 10.1.0.0、10.1.3.255、1022;/24 → 10.1.2.0、10.1.2.255、254。再看 172.16.5.9/20:网络号 172.16.0.0、广播 172.16.15.255、4094 台;192.0.2.77/26:网络号 192.0.2.64、广播 192.0.2.127、62 台;/28 → 14 台;/30 → 2 台(192.0.2.77~78)。规律:前缀每加 1 位,地址数减半;可用主机数 = 2^(32−前缀) − 2。通配符掩码就是掩码按位取反,ACL 和路由协议里用它。", t=tl(S(1)), mark=lidx(S(1), '10.1.2.200/22', '172.16.5.9/20'), done=lidx(S(1), '10.1.2.200/8', '10.1.2.200/24', '192.0.2.77/26', '192.0.2.77/28', '192.0.2.77/30'), b=bars([['/8', 16777214, '16777214'], ['/16', 65534, '65534'], ['/22', 1022, '1022'], ['/24', 254, '254'], ['/26', 62, '62'], ['/28', 14, '14'], ['/30', 2, '2']], 16777214, mark=[2], done=[0, 1, 3, 4, 5, 6]), kv=KV([['前缀 +1 位', '地址数减半'], ['可用主机数', '2^(32−前缀) − 2'], ['通配符', '掩码按位取反']], ['可用主机数'])),
    step("/31 和 /32 是特殊情况:192.0.2.4/30 有 4 个地址(4~7,去掉网络号 4 和广播 7 剩 2 个可用);192.0.2.4/31 只有 2 个地址(4、5),没有网络号和广播——RFC 3021 允许它用在点对点链路上,两个都是主机;/32 只有 1 个地址,就是一个主机路由。ipaddress 的 hosts() 在 /30、/31、/32 上分别返回 2、2、1 个地址,与这些约定一致。", t=tl(S(2)), mark=lidx(S(2), '/31:', '/32:'), done=lidx(S(2), '/30:', 'hosts()'), kv=KV([['/30', '4 个地址,2 个可用'], ['/31', '2 个地址,都可用(点对点)'], ['/32', '1 个地址(主机路由)']], ['/31'])),
    step("划分(VLSM):把 10.0.0.0/24 切给四个部门,需要主机 60、28、12、2 台。从大到小,每个选刚好够用的最小前缀,并且起点对齐到自己的大小:A 60 台 → 10.0.0.0/26(62 台可用);B 28 台 → 10.0.0.64/27(30 台);C 12 台 → 10.0.0.96/28(14 台);D 2 台 → 10.0.0.112/30(2 台)。四个子网互不重叠(overlaps 检查为 False),共用掉 116 个地址,/24 里还剩 140 个。从大到小分配、起点对齐,是避免碎片和重叠的关键。", t=tl(S(3)), mark=lidx(S(3), '部门 A', '互不重叠'), done=lidx(S(3), '部门 B', '部门 C', '部门 D'), b=bars([['A /26', 64, '64 个地址'], ['B /27', 32, '32 个地址'], ['C /28', 16, '16 个地址'], ['D /30', 4, '4 个地址'], ['剩余', 140, '140 个地址']], 140, mark=[4], done=[0, 1, 2, 3]), kv=KV([['分配顺序', '从大到小'], ['起点', '必须对齐到自己的大小'], ['结果', '116 个地址已用,不重叠']], ['起点'])),
    step("汇总(路由聚合):10.8.0.0/24 ~ 10.8.7.0/24 这 8 个连续的 /24 合并成一条 10.8.0.0/21;但 10.8.1.0/24 ~ 10.8.4.0/24 这 4 个(从 1 开始、没有对齐到 4 的倍数)只能合成 10.8.1.0/24 + 10.8.2.0/23 + 10.8.4.0/24 三条;10.8.0/24、.1、.2、.4(缺 .3)合成 10.8.0.0/23 + 10.8.2.0/24 + 10.8.4.0/24。聚合要求个数是 2 的幂、起点按这个大小对齐(/21 的起点必须是 8 的倍数),否则只能合并一部分。路由器聚合路由,表里的条目就少。", t=tl(S(4)), mark=lidx(S(4), '10.8.0.0/24 ~ 10.8.7.0/24'), done=lidx(S(4), '10.8.1.0/24', '缺 .3', '聚合要求'), b=bars([['8 个 /24 → 1 条', 1, '1 条 /21'], ['从 1 开始的 4 个 → 3 条', 3, '3 条'], ['缺 .3 的 4 个 → 3 条', 3, '3 条']], 3, mark=[0], done=[1, 2]), kv=KV([['可合并', '个数 2 的幂 + 起点对齐'], ['8 个连续 /24', '→ 1 条 /21'], ['没对齐', '合不拢']], ['可合并'])),
    step("判断“某个 IP 在不在子网里”只要一次与运算:(ip AND mask) == network。100 万个 172.16.0.0/16 里的随机地址,落在 172.16.0.0/20 内的有 62318 个(约 1/16),用 ipaddress 对象判断 254 ms,用整数 (ip & mask) == network 只要 36 ms,快 7 倍,结果一致。路由器做最长前缀匹配就是在做这个运算(再配上特殊的数据结构一次比较很多条)。", t=tl(S(5)), mark=lidx(S(5), 'ipaddress.ip_address()'), done=lidx(S(5), '100 万个'), b=bars([['ipaddress 对象', 254, '254 ms'], ['整数位运算', 36, '36 ms']], 254, mark=[1], done=[0]), kv=KV([['判断', '(ip & mask) == network'], ['100 万次', '254 ms vs 36 ms'], ['路由器', '最长前缀匹配用的就是它']], ['判断'])),
    step("这台机器的路由表(netstat -rn -f inet)里的目的地写法:default = 0.0.0.0/0,127 = 127.0.0.0/8,169.254 = 169.254.0.0/16,局域网那条带 /22,224.0.0/4 是组播,255.255.255.255/32 是受限广播——netstat 把目的地末尾的 0 省略,前缀长度单独写在 /N 里。共 198 条目的地,前缀分布 /0×1、/4×1、/22×1、/32×195;其中 33 条是 169.254.x.x 邻居的主机路由(ARP 学来的,标志 UHLSW)。", t=tl(S(6)), mark=lidx(S(6), '路由表共', 'default', '169.254  '), done=lidx(S(6), '127  ', '224.0.0/4', '255.255.255.255/32', '另有 33'), b=bars([['/0 默认', 1, '1'], ['/4 组播', 1, '1'], ['/22 局域网', 1, '1'], ['/32 主机路由', 195, '195']], 195, mark=[3], done=[0, 1, 2]), kv=KV([['default', '0.0.0.0/0'], ['127', '127.0.0.0/8'], ['/32', '主机路由,绝大多数是邻居']], ['/32'])),
]
